/// @brief Enumeration for Contacts match string flags.
/// @since_tizen @if MOBILE 2.3 @elseif WEARABLE 3.0 @endif
abstract class contacts_match_str_flag_e {
  /// < Full string, case-sensitive
  static const int CONTACTS_MATCH_EXACTLY = 0;

  /// < Full string, case-insensitive
  static const int CONTACTS_MATCH_FULLSTRING = 1;

  /// < Sub string, case-insensitive
  static const int CONTACTS_MATCH_CONTAINS = 2;

  /// < Start with, case-insensitive
  static const int CONTACTS_MATCH_STARTSWITH = 3;

  /// < End with, case-insensitive
  static const int CONTACTS_MATCH_ENDSWITH = 4;

  /// < IS NOT NULL
  static const int CONTACTS_MATCH_EXISTS = 5;
}

/// @brief Enumeration for Contacts match int flags.
/// @since_tizen @if MOBILE 2.3 @elseif WEARABLE 3.0 @endif
abstract class contacts_match_int_flag_e {
  /// < '='
  static const int CONTACTS_MATCH_EQUAL = 0;

  /// < '>'
  static const int CONTACTS_MATCH_GREATER_THAN = 1;

  /// < '>='
  static const int CONTACTS_MATCH_GREATER_THAN_OR_EQUAL = 2;

  /// < '<'
  static const int CONTACTS_MATCH_LESS_THAN = 3;

  /// < '<='
  static const int CONTACTS_MATCH_LESS_THAN_OR_EQUAL = 4;

  /// < '<>', this flag can yield poor performance
  static const int CONTACTS_MATCH_NOT_EQUAL = 5;

  /// < IS NULL
  static const int CONTACTS_MATCH_NONE = 6;
}

